alter table dm_private.papers drop constraint papers_source_kind_check;
alter table dm_private.papers add constraint papers_source_kind_check check(source_kind in('catalogue','topic','exam','exam_part_b','all_india'));

create table dm_private.exam_mock_sessions(
 id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id)on delete cascade,
 exam text not null check(exam in('uceed','ceed')),part_a_attempt uuid not null unique references dm_private.attempts(id)on delete cascade,
 part_b_attempt uuid unique references dm_private.attempts(id)on delete set null,created_at timestamptz not null default now()
);
alter table dm_private.exam_mock_sessions enable row level security;
revoke all on dm_private.exam_mock_sessions from anon,authenticated;

create or replace function dm_private.create_exam_mock_session()returns trigger language plpgsql security definer set search_path=pg_catalog,dm_private as $$
declare p dm_private.papers;
begin select*into p from dm_private.papers where id=new.paper_id;if p.source_kind='exam'and p.exam in('uceed','ceed')then insert into dm_private.exam_mock_sessions(user_id,exam,part_a_attempt)values(new.user_id,p.exam,new.id);end if;return new;end$$;
create trigger create_exam_mock_session after insert on dm_private.attempts for each row execute function dm_private.create_exam_mock_session();

create or replace function public.my_exam_mock_session(p_attempt_id uuid)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,dm_private as $$
declare s dm_private.exam_mock_sessions;a dm_private.attempts;v_tasks integer;v_duration integer;v_state text;
begin select*into s from dm_private.exam_mock_sessions where user_id=auth.uid()and(part_a_attempt=p_attempt_id or part_b_attempt=p_attempt_id);if s.id is null then return null;end if;select*into a from dm_private.attempts where id=s.part_a_attempt;v_tasks:=case when s.exam='uceed'then 2 else 5 end;v_duration:=case when s.exam='uceed'then 3600 else 7200 end;v_state:=case when s.part_b_attempt is not null then'started'when a.status<>'submitted'then'part_a_active'when now()<a.deadline then'waiting'when now()>=a.deadline+make_interval(secs=>v_duration)then'closed'else'ready'end;return jsonb_build_object('sessionId',s.id,'exam',s.exam,'partAAttemptId',s.part_a_attempt,'partBAttemptId',s.part_b_attempt,'partBState',v_state,'partBOpensAt',a.deadline,'partBClosesAt',a.deadline+make_interval(secs=>v_duration),'partBDurationSeconds',v_duration,'partBTaskCount',v_tasks);end$$;

create or replace function public.start_exam_mock_part_b(p_part_a_attempt uuid)returns uuid language plpgsql security definer set search_path=pg_catalog,dm_private as $$
declare s dm_private.exam_mock_sessions;a dm_private.attempts;v_tasks integer;v_duration integer;v_paper uuid;v_attempt uuid;v_question record;v_question_id uuid;v_ordinal integer:=0;v_seed uuid:=gen_random_uuid();
begin if auth.uid()is null then raise exception'Sign in required';end if;perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text,19));select*into s from dm_private.exam_mock_sessions where user_id=auth.uid()and part_a_attempt=p_part_a_attempt for update;if s.id is null then raise exception'Exam session not found';end if;if s.part_b_attempt is not null then return s.part_b_attempt;end if;select*into a from dm_private.attempts where id=s.part_a_attempt for update;if a.status<>'submitted'then raise exception'Submit Part A first';end if;v_tasks:=case when s.exam='uceed'then 2 else 5 end;v_duration:=case when s.exam='uceed'then 3600 else 7200 end;if now()<a.deadline then raise exception'Part B opens when the Part A clock ends';end if;if now()>=a.deadline+make_interval(secs=>v_duration)then raise exception'Part B window has closed';end if;if(select count(*)from dm_private.bank_questions where exam=s.exam and active and owner_approved and rights_confirmed and runtime_payload->>'kind'='drawing'and(runtime_payload->>'points')::numeric=case when s.exam='uceed'then 50 else 20 end and runtime_payload->'marking'->>'humanReview'='true'and runtime_payload->'context'->>'version'='iitb-2027-v1'and runtime_payload->'context'->>'section'='Part B'and jsonb_typeof(runtime_payload->'media')='array'and jsonb_array_length(runtime_payload->'media')>0)<v_tasks then raise exception'Not enough reviewed Part B tasks';end if;insert into dm_private.papers(title,exam,duration_seconds,published,reviewed,rights_confirmed,owner_user_id,source_kind,upload_grace_seconds)values(upper(s.exam)||' 2027 Part B mock',s.exam,v_duration,false,true,true,auth.uid(),'exam_part_b',900)returning id into v_paper;for v_question in select*from dm_private.bank_questions where exam=s.exam and active and owner_approved and rights_confirmed and runtime_payload->>'kind'='drawing'and(runtime_payload->>'points')::numeric=case when s.exam='uceed'then 50 else 20 end and runtime_payload->'marking'->>'humanReview'='true'and runtime_payload->'context'->>'version'='iitb-2027-v1'and runtime_payload->'context'->>'section'='Part B'and jsonb_typeof(runtime_payload->'media')='array'and jsonb_array_length(runtime_payload->'media')>0 order by md5(external_key||v_seed::text)limit v_tasks loop v_ordinal:=v_ordinal+1;insert into dm_private.questions(paper_id,ordinal,prompt,options,kind,marking,media,points,negative_points,topic,reviewed)values(v_paper,v_ordinal,v_question.runtime_payload->>'prompt',v_question.runtime_payload->'options','drawing',v_question.runtime_payload->'marking',v_question.runtime_payload->'media',(v_question.runtime_payload->>'points')::numeric,0,v_question.topic,true)returning id into v_question_id;insert into dm_private.answer_keys(question_id,key,explanation)values(v_question_id,v_question.runtime_payload->'key',v_question.runtime_payload->>'explanation');end loop;if v_ordinal<>v_tasks then raise exception'Frozen Part B does not match verified manifest';end if;insert into dm_private.attempts(user_id,paper_id,deadline)values(auth.uid(),v_paper,a.deadline+make_interval(secs=>v_duration))returning id into v_attempt;insert into dm_private.attempt_items(attempt_id,question_id,ordinal,prompt,options,points,negative_points,topic,kind,marking,media,key,explanation)select v_attempt,q.id,q.ordinal,q.prompt,q.options,q.points,q.negative_points,q.topic,q.kind,q.marking,q.media,k.key,k.explanation from dm_private.questions q join dm_private.answer_keys k on k.question_id=q.id where q.paper_id=v_paper;update dm_private.exam_mock_sessions set part_b_attempt=v_attempt where id=s.id;return v_attempt;end$$;

revoke all on function public.my_exam_mock_session(uuid),public.start_exam_mock_part_b(uuid)from public,anon;
grant execute on function public.my_exam_mock_session(uuid),public.start_exam_mock_part_b(uuid)to authenticated;
